-- =====================================================================
-- SUPREMA - SCHEMA (PostgreSQL / Supabase)
--
-- Converted from the original MySQL schema. The changes that matter:
--
--   INT AUTO_INCREMENT          -> INT GENERATED BY DEFAULT AS IDENTITY
--   ENUM('a','b')               -> TEXT + a CHECK constraint
--   TIMESTAMP / DATETIME        -> TIMESTAMPTZ (always stored as UTC)
--   JSON                        -> JSONB
--   TINYINT(1)                  -> BOOLEAN
--   LONGTEXT                    -> TEXT
--   INDEX inside CREATE TABLE   -> a separate CREATE INDEX statement
--   ON UPDATE CURRENT_TIMESTAMP -> a BEFORE UPDATE trigger
--
-- "BY DEFAULT" (rather than "ALWAYS") on the identity columns so the seed
-- data and the test fixtures can still insert explicit ids.
-- =====================================================================

-- Drop in one statement, CASCADE so the foreign keys between them do not
-- have to be dropped in any particular order.
DROP TABLE IF EXISTS
  blogs, pricing_plans, changelogs, waitlist_leads, contact_messages,
  password_reset_tokens, email_verifications, notifications, activity_logs,
  task_attachments, task_comments, tasks, projects, team_members, teams,
  workspace_invitations, workspace_members, workspaces, users
CASCADE;

-- Keeps `updated_at` honest the way MySQL's ON UPDATE CURRENT_TIMESTAMP did.
CREATE OR REPLACE FUNCTION set_updated_at() RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- 1. USERS TABLE
CREATE TABLE IF NOT EXISTS users (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL UNIQUE,
    password_hash VARCHAR(255) NOT NULL,
    avatar_url VARCHAR(255) DEFAULT NULL,
    role TEXT NOT NULL DEFAULT 'member'
        CONSTRAINT chk_users_role CHECK (role IN ('super_admin','admin','developer','member','viewer')),
    status TEXT NOT NULL DEFAULT 'active'
        CONSTRAINT chk_users_status CHECK (status IN ('active','inactive','suspended')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_users_email ON users (email);
CREATE INDEX IF NOT EXISTS idx_users_role ON users (role);
CREATE TRIGGER trg_users_updated_at BEFORE UPDATE ON users
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 2. WORKSPACES TABLE (Multi-Tenancy)
CREATE TABLE IF NOT EXISTS workspaces (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    slug VARCHAR(100) NOT NULL UNIQUE,
    owner_id INT NOT NULL,
    plan TEXT NOT NULL DEFAULT 'free'
        CONSTRAINT chk_workspaces_plan CHECK (plan IN ('free','pro','enterprise')),
    -- 'archived' freezes a workspace: it disappears from the switcher and
    -- from normal use, but every row of data is kept and it can be restored.
    -- A permanent delete is a separate, super-admin-only action.
    status TEXT NOT NULL DEFAULT 'active'
        CONSTRAINT chk_workspaces_status CHECK (status IN ('active','archived')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (owner_id) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_workspaces_slug ON workspaces (slug);
CREATE INDEX IF NOT EXISTS idx_workspaces_owner ON workspaces (owner_id);
CREATE INDEX IF NOT EXISTS idx_workspaces_status ON workspaces (status);
CREATE TRIGGER trg_workspaces_updated_at BEFORE UPDATE ON workspaces
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 3. WORKSPACE MEMBERS TABLE
CREATE TABLE IF NOT EXISTS workspace_members (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id INT NOT NULL,
    user_id INT NOT NULL,
    role TEXT NOT NULL DEFAULT 'member'
        CONSTRAINT chk_wm_role CHECK (role IN ('owner','admin','member','guest')),
    joined_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT uk_workspace_user UNIQUE (workspace_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_wm_workspace ON workspace_members (workspace_id);
CREATE INDEX IF NOT EXISTS idx_wm_user ON workspace_members (user_id);

-- 3b. WORKSPACE INVITATIONS TABLE
-- A pending request to join a workspace. The membership row in
-- workspace_members is only created once the invitee ACCEPTS, so joining a
-- workspace is a decision the invited person makes rather than something
-- that happens to them silently.
CREATE TABLE IF NOT EXISTS workspace_invitations (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id INT NOT NULL,
    user_id INT NOT NULL,
    email VARCHAR(150) NOT NULL,
    role TEXT NOT NULL DEFAULT 'member'
        CONSTRAINT chk_wi_role CHECK (role IN ('owner','admin','member','guest')),
    invited_by INT NOT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
        CONSTRAINT chk_wi_status CHECK (status IN ('pending','accepted','rejected')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    responded_at TIMESTAMPTZ DEFAULT NULL,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    FOREIGN KEY (invited_by) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_wi_workspace ON workspace_invitations (workspace_id);
CREATE INDEX IF NOT EXISTS idx_wi_user ON workspace_invitations (user_id);
CREATE INDEX IF NOT EXISTS idx_wi_status ON workspace_invitations (status);

-- 4. TEAMS TABLE
CREATE TABLE IF NOT EXISTS teams (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id INT NOT NULL,
    name VARCHAR(100) NOT NULL,
    description TEXT DEFAULT NULL,
    created_by INT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_teams_workspace ON teams (workspace_id);
CREATE INDEX IF NOT EXISTS idx_teams_created_by ON teams (created_by);

-- 5. TEAM MEMBERS TABLE
CREATE TABLE IF NOT EXISTS team_members (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    team_id INT NOT NULL,
    user_id INT NOT NULL,
    role TEXT NOT NULL DEFAULT 'member'
        CONSTRAINT chk_tm_role CHECK (role IN ('leader','member')),
    joined_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT uk_team_user UNIQUE (team_id, user_id)
);
CREATE INDEX IF NOT EXISTS idx_tm_team ON team_members (team_id);
CREATE INDEX IF NOT EXISTS idx_tm_user ON team_members (user_id);

-- 6. PROJECTS TABLE
CREATE TABLE IF NOT EXISTS projects (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id INT NOT NULL,
    team_id INT DEFAULT NULL,
    name VARCHAR(150) NOT NULL,
    description TEXT DEFAULT NULL,
    status TEXT NOT NULL DEFAULT 'active'
        CONSTRAINT chk_projects_status CHECK (status IN ('planning','active','on_hold','completed','archived')),
    color VARCHAR(20) DEFAULT '#6366f1',
    start_date DATE DEFAULT NULL,
    due_date DATE DEFAULT NULL,
    created_by INT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
    FOREIGN KEY (team_id) REFERENCES teams(id) ON DELETE SET NULL,
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS idx_projects_workspace ON projects (workspace_id);
CREATE INDEX IF NOT EXISTS idx_projects_team ON projects (team_id);
CREATE INDEX IF NOT EXISTS idx_projects_status ON projects (status);
CREATE TRIGGER trg_projects_updated_at BEFORE UPDATE ON projects
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 7. TASKS TABLE (Supports Subtasks via parent_id)
CREATE TABLE IF NOT EXISTS tasks (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id INT NOT NULL,
    title VARCHAR(255) NOT NULL,
    description TEXT DEFAULT NULL,
    status TEXT NOT NULL DEFAULT 'todo'
        CONSTRAINT chk_tasks_status CHECK (status IN ('todo','in_progress','in_review','done')),
    priority TEXT NOT NULL DEFAULT 'medium'
        CONSTRAINT chk_tasks_priority CHECK (priority IN ('low','medium','high','urgent')),
    -- A DATE, not a TIMESTAMPTZ: the task form sends a plain 'YYYY-MM-DD' and
    -- the app reads it back as a string (due_date.substring(0, 10)), which is
    -- exactly what PostgreSQL returns for a DATE column. A TIMESTAMPTZ would
    -- arrive as a JavaScript Date and break those string operations.
    due_date DATE DEFAULT NULL,
    estimated_hours DECIMAL(5,2) DEFAULT 0.00,
    actual_hours DECIMAL(5,2) DEFAULT 0.00,
    created_by INT NOT NULL,
    assignee_id INT DEFAULT NULL,
    parent_id INT DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (project_id) REFERENCES projects(id) ON DELETE CASCADE,
    FOREIGN KEY (created_by) REFERENCES users(id) ON DELETE RESTRICT,
    FOREIGN KEY (assignee_id) REFERENCES users(id) ON DELETE SET NULL,
    FOREIGN KEY (parent_id) REFERENCES tasks(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_tasks_project ON tasks (project_id);
CREATE INDEX IF NOT EXISTS idx_tasks_assignee ON tasks (assignee_id);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON tasks (status);
CREATE INDEX IF NOT EXISTS idx_tasks_priority ON tasks (priority);
CREATE INDEX IF NOT EXISTS idx_tasks_parent ON tasks (parent_id);
CREATE TRIGGER trg_tasks_updated_at BEFORE UPDATE ON tasks
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 8. TASK COMMENTS TABLE
CREATE TABLE IF NOT EXISTS task_comments (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id INT NOT NULL,
    user_id INT NOT NULL,
    content TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_comments_task ON task_comments (task_id);
CREATE INDEX IF NOT EXISTS idx_comments_user ON task_comments (user_id);
CREATE TRIGGER trg_comments_updated_at BEFORE UPDATE ON task_comments
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- 9. TASK ATTACHMENTS TABLE
CREATE TABLE IF NOT EXISTS task_attachments (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    task_id INT NOT NULL,
    user_id INT NOT NULL,
    filename VARCHAR(255) NOT NULL,
    original_name VARCHAR(255) NOT NULL,
    file_path VARCHAR(500) NOT NULL,
    file_size INT NOT NULL,
    mime_type VARCHAR(100) NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_attachments_task ON task_attachments (task_id);

-- 10. ACTIVITY LOGS TABLE (Audit Trail)
CREATE TABLE IF NOT EXISTS activity_logs (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    workspace_id INT NOT NULL,
    user_id INT DEFAULT NULL,
    action VARCHAR(100) NOT NULL,
    entity_type VARCHAR(50) NOT NULL,
    entity_id INT DEFAULT NULL,
    details JSONB DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (workspace_id) REFERENCES workspaces(id) ON DELETE CASCADE,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL
);
CREATE INDEX IF NOT EXISTS idx_activity_workspace ON activity_logs (workspace_id);
CREATE INDEX IF NOT EXISTS idx_activity_user ON activity_logs (user_id);
CREATE INDEX IF NOT EXISTS idx_activity_action ON activity_logs (action);

-- 11. NOTIFICATIONS TABLE
CREATE TABLE IF NOT EXISTS notifications (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL,
    title VARCHAR(200) NOT NULL,
    message TEXT NOT NULL,
    type TEXT NOT NULL DEFAULT 'info'
        CONSTRAINT chk_notifications_type CHECK (type IN ('info','task_assigned','mention','system','announcement','invitation')),
    is_read BOOLEAN NOT NULL DEFAULT FALSE,
    link VARCHAR(255) DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications (user_id);
CREATE INDEX IF NOT EXISTS idx_notifications_read ON notifications (is_read);

-- 12. EMAIL VERIFICATIONS TABLE (OTP Codes)
CREATE TABLE IF NOT EXISTS email_verifications (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(150) NOT NULL,
    otp_code VARCHAR(10) NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_ev_email ON email_verifications (email);
CREATE INDEX IF NOT EXISTS idx_ev_code ON email_verifications (otp_code);

-- 12b. SELF-SERVICE PASSWORD RESET TOKENS
-- token_hash is SHA-256, never the token itself: a leaked database must not
-- hand an attacker usable reset links. used_at makes each token single-use.
CREATE TABLE IF NOT EXISTS password_reset_tokens (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id INT NOT NULL,
    token_hash CHAR(64) NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    used_at TIMESTAMPTZ DEFAULT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE CASCADE,
    CONSTRAINT uq_password_reset_token UNIQUE (token_hash)
);
CREATE INDEX IF NOT EXISTS idx_password_reset_user ON password_reset_tokens (user_id);
CREATE INDEX IF NOT EXISTS idx_password_reset_expiry ON password_reset_tokens (expires_at);

-- 13. MARKETING: CONTACT MESSAGES TABLE
CREATE TABLE IF NOT EXISTS contact_messages (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(100) NOT NULL,
    email VARCHAR(150) NOT NULL,
    subject VARCHAR(200) DEFAULT 'Website Inquiry',
    message TEXT NOT NULL,
    status TEXT NOT NULL DEFAULT 'unread'
        CONSTRAINT chk_contact_status CHECK (status IN ('unread','read','replied')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE INDEX IF NOT EXISTS idx_contact_status ON contact_messages (status);
CREATE INDEX IF NOT EXISTS idx_contact_created ON contact_messages (created_at);

-- 14. MARKETING: WAITLIST SIGNUPS TABLE
-- queue_position is assigned from MAX(queue_position)+1 at insert time, so the
-- stored number always reflects the order people actually joined.
CREATE TABLE IF NOT EXISTS waitlist_leads (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email VARCHAR(150) NOT NULL,
    queue_position INT DEFAULT NULL,
    referral_code VARCHAR(50) DEFAULT NULL,
    status TEXT NOT NULL DEFAULT 'pending'
        CONSTRAINT chk_waitlist_status CHECK (status IN ('pending','invited','active')),
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_waitlist_email UNIQUE (email)
);
CREATE INDEX IF NOT EXISTS idx_waitlist_position ON waitlist_leads (queue_position);

-- 15. MARKETING: CHANGELOG ENTRIES TABLE
CREATE TABLE IF NOT EXISTS changelogs (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    tag_id VARCHAR(100) NOT NULL,
    date VARCHAR(50) NOT NULL,
    badge VARCHAR(50) DEFAULT 'New',
    badge_color VARCHAR(50) DEFAULT 'text-emerald-400',
    title VARCHAR(255) NOT NULL,
    description TEXT,
    sub_item_title VARCHAR(255) DEFAULT NULL,
    sub_item_description TEXT,
    tag VARCHAR(100) DEFAULT NULL,
    banner_title VARCHAR(255) DEFAULT NULL,
    bullets JSONB DEFAULT NULL,
    note TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_changelog_tag UNIQUE (tag_id)
);
CREATE INDEX IF NOT EXISTS idx_changelog_badge ON changelogs (badge);

-- 16. MARKETING: PRICING PLANS TABLE
CREATE TABLE IF NOT EXISTS pricing_plans (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    plan_id VARCHAR(50) NOT NULL,
    name VARCHAR(100) NOT NULL,
    price_monthly VARCHAR(50) DEFAULT NULL,
    price_yearly VARCHAR(50) DEFAULT NULL,
    period VARCHAR(50) DEFAULT 'per user / month',
    subtext VARCHAR(100) DEFAULT NULL,
    popular BOOLEAN DEFAULT FALSE,
    popular_badge VARCHAR(50) DEFAULT NULL,
    has_toggle BOOLEAN DEFAULT TRUE,
    btn_variant VARCHAR(50) DEFAULT 'dark',
    btn_text VARCHAR(50) DEFAULT 'Get Started',
    features JSONB DEFAULT NULL,
    sort_order INT DEFAULT 0,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_plan_id UNIQUE (plan_id)
);
CREATE INDEX IF NOT EXISTS idx_plan_sort ON pricing_plans (sort_order);

-- 17. BLOG POSTS TABLE (Admin CMS + Public /blog page)
-- Staff write via /dashboard/blog-admin; the public BlogPage reads the same rows.
CREATE TABLE IF NOT EXISTS blogs (
    id INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title VARCHAR(255) NOT NULL,
    slug VARCHAR(255) NOT NULL,
    banner_title VARCHAR(255) DEFAULT NULL,
    excerpt TEXT,
    content TEXT,
    sections JSONB DEFAULT NULL,
    category VARCHAR(100) DEFAULT NULL,
    category_color VARCHAR(50) DEFAULT 'text-emerald-400',
    category_bg VARCHAR(100) DEFAULT 'bg-emerald-500/10 border-emerald-500/20',
    date VARCHAR(50) DEFAULT NULL,
    author_name VARCHAR(100) DEFAULT NULL,
    author_role VARCHAR(100) DEFAULT NULL,
    author_handle VARCHAR(100) DEFAULT NULL,
    author_bio TEXT DEFAULT NULL,
    author_avatar VARCHAR(500) DEFAULT NULL,
    cover_image VARCHAR(500) DEFAULT NULL,
    tags JSONB DEFAULT NULL,
    featured BOOLEAN NOT NULL DEFAULT FALSE,
    read_time VARCHAR(50) DEFAULT '5 min read',
    status TEXT NOT NULL DEFAULT 'published'
        CONSTRAINT chk_blogs_status CHECK (status IN ('draft','published','archived')),
    published_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uq_blog_slug UNIQUE (slug)
);
CREATE INDEX IF NOT EXISTS idx_blog_status ON blogs (status);
CREATE INDEX IF NOT EXISTS idx_blog_category ON blogs (category);
CREATE INDEX IF NOT EXISTS idx_blog_featured ON blogs (featured);
CREATE INDEX IF NOT EXISTS idx_blog_published ON blogs (published_at);
CREATE TRIGGER trg_blogs_updated_at BEFORE UPDATE ON blogs
    FOR EACH ROW EXECUTE FUNCTION set_updated_at();
